                <button
                  type="button"
                  onClick={() => setShowAdvancedSearch(false)}
                  className="px-4 py-1.5 rounded-full text-xs font-medium bg-[#0B57D0] text-white hover:bg-[#0842A0] transition-colors cursor-pointer"
