+                    { id: 'archive', label: 'All Mail (Archive)', icon: Archive },
+                    { id: 'spam', label: 'Spam', icon: AlertOctagon },
+                    { id: 'trash', label: 'Trash', icon: Trash2 },
+                  ].map((dest) => {
+                    const DestIcon = dest.icon;
+                    return (
