                        <ChevronDown className="w-3.5 h-3.5" />
                      </button>
                    </div>
                  </div>
                </div>

                {/* Right Timestamp + Message Quick Controls */}
                <div className="flex items-center gap-1 shrink-0 text-xs">
                  <span className="opacity-70 tabular-nums mr-1 hidden sm:inline">
                    {msg.displayTime}
