                        </span>
                        {active && <Check className="w-3.5 h-3.5 text-[#0B57D0]" />}
                      </button>
                    );
                  })}
                </div>
              )}
            </div>
          </div>
        </div>

        {/* Right Header Actions */}
        <div className="flex items-center gap-1 shrink-0">
          {thread.messages.length > 1 && (
            <button
              type="button"
