                        ? 'hover:bg-[#282A2C] opacity-65'
                        : 'hover:bg-[#E8EAED] opacity-65'
                    }`}
                  >
                    <Star
                      className="w-4 h-4"
                      fill={thread.isStarred ? '#F4B400' : 'none'}
                    />
                  </button>
                  <button
                    type="button"
                    onClick={() => startInlineCompose('reply')}
                    aria-label="Reply"
                    title="Reply (r)"
