                      isDark ? 'hover:bg-[#282A2C] opacity-75' : 'hover:bg-[#E8EAED] opacity-75'
                    }`}
                  >
                    <Reply className="w-4 h-4" />
                  </button>
                  <button
                    type="button"
                    onClick={() => startInlineCompose('forward')}
                    aria-label="Forward"
                    title="Forward (f)"
