                <div
                  className={`mt-4 ml-0 sm:ml-13 rounded-2xl border p-4 max-w-2xl ${
                    isDark
                      ? 'bg-[#25272A] border-[#444746]'
                      : 'bg-[#F8FAFD] border-[#D3E3FD]'
