              <div
                className={`mt-4 ml-0 sm:ml-13 max-w-[74ch] text-[14.5px] leading-[1.62] space-y-3 message-body ${
                  isDark ? 'text-[#E3E3E3]' : 'text-[#1F1F1F]'
