                dangerouslySetInnerHTML={{ __html: msg.body }}
              />

              {/* Message Attachments Grid */}
              {msg.attachments && msg.attachments.length > 0 && (
                <div className="mt-5 ml-0 sm:ml-13 pt-3 border-t border-current/10">
