                  </strong>{' '}
                  &lt;
                  {lastMsg.sender.id === currentUser.id
                    ? lastMsg.to[0]?.email
                    : lastMsg.sender.email}
                  &gt;
                </span>
              )}
            </div>

            <button
              type="button"
              onClick={() => {
                onPopOutReply(thread, replyMode, replyBody);
                setReplyMode(null);
