+            {/* Thread List Pane */}
+            {!isDetailViewOnly && (
+              <div
+                className={`flex flex-col min-w-0 min-h-0 ${
+                  settings.readingPane === 'right'
+                    ? 'w-full lg:w-[46%] lg:border-r'
+                    : settings.readingPane === 'bottom'
+                    ? 'h-[48%] border-b'
+                    : 'flex-1'
+                } ${isDark ? 'border-[#282A2C]' : 'border-[#E8EAED]'}`}
+              >
