+                  onPreviewAttachment={setPreviewAttachment}
+                  activeThreadId={activeThreadId}
+                  focusedIndex={focusedIndex}
+                  onSetFocusedIndex={setFocusedIndex}
+                  labels={labels}
+                  density={settings.density}
+                  filters={filters}
+                  onResetFilters={() => {
