import { chromium } from 'playwright';
import fs from 'fs';
import path from 'path';

const outDir = path.resolve('./tmp-screenshots');
fs.mkdirSync(outDir, { recursive: true });

const browser = await chromium.launch({ headless: true });
const context = await browser.newContext({ viewport: { width: 1440, height: 900 } });
const page = await context.newPage();

const errors = [];
page.on('console', (msg) => {
  if (msg.type() === 'error') errors.push(msg.text());
});
page.on('pageerror', (err) => {
  errors.push(err.message);
});

await page.goto('http://localhost:9387/', { waitUntil: 'networkidle' });

// 1. Check browser title and primary visible title
const title = await page.title();
const h1Text = await page.locator('h1').textContent();
console.log('Browser title:', JSON.stringify(title));
console.log('Primary visible h1:', JSON.stringify(h1Text));
if (title !== 'Gemini 4 Argon' || h1Text !== 'Gemini 4 Argon') {
  throw new Error(`Title mismatch: title=${title}, h1=${h1Text}`);
}

await page.screenshot({ path: path.join(outDir, '01-inbox-light.png') });

// 2. Test Category Tabs
await page.getByRole('tab', { name: /Promotions/i }).click();
await page.waitForTimeout(150);
const promoCount = await page.getByRole('listitem').count();
console.log('Promotions threads count:', promoCount);

await page.getByRole('tab', { name: /Updates/i }).click();
await page.waitForTimeout(150);
const updatesCount = await page.getByRole('listitem').count();
console.log('Updates threads count:', updatesCount);

await page.getByRole('tab', { name: /Primary/i }).click();
await page.waitForTimeout(150);

// 3. Test Search & Filter Chips
const searchInput = page.getByLabel('Search mail');
await searchInput.click();
await searchInput.fill('Raft');
await page.keyboard.press('Enter');
await page.waitForTimeout(150);
const searchResults = await page.getByRole('listitem').count();
console.log('Search "Raft" results:', searchResults);
await page.screenshot({ path: path.join(outDir, '02-search-results.png') });

await page.getByLabel('Clear search').click();
await page.waitForTimeout(150);

// 4. Open Multi-Message Thread & Inspect Conversation View
await page.getByText('Multi-region Raft consensus cutover').first().click();
await page.waitForTimeout(250);
await page.screenshot({ path: path.join(outDir, '03-thread-view.png') });

// Click RSVP 'Yes' on Calendar Invite
await page.getByRole('button', { name: /^yes$/i }).click();
await page.waitForTimeout(150);

// Preview an attachment
await page.getByText('eu-central-1-jepsen-report.pdf').first().click();
await page.waitForTimeout(200);
await page.screenshot({ path: path.join(outDir, '04-attachment-preview.png') });
await page.getByLabel('Close preview').click();
await page.waitForTimeout(150);

// Send a Smart Reply
await page.getByText('Confirmed for 2:00 PM PT — rollback thresholds look solid.').click();
await page.waitForTimeout(150);
await page.getByRole('button', { name: /^Send$/i }).click();
await page.waitForTimeout(200);

// Back to inbox list
await page.getByLabel('Back to thread list').click();
await page.waitForTimeout(150);

// 5. Test Compose & Send Flow
await page.getByRole('button', { name: /Compose/i }).click();
await page.waitForTimeout(200);
await page.getByLabel('To recipients').fill('elena.rostova@acme.dev');
await page.keyboard.press('Enter');
await page.getByLabel('Subject').fill('Automated E2E Verification Complete');
await page.getByLabel('Message body').fill('Verified inbox, threads, search, attachments, and compose workflows.');
await page.screenshot({ path: path.join(outDir, '05-compose-modal.png') });

await page.getByRole('dialog', { name: 'Compose message' }).getByRole('button', { name: /^Send$/i }).click();
await page.waitForTimeout(200);

// Navigate to Sent folder and verify sent email is there
await page.getByRole('button', { name: /^Sent/i }).click();
await page.waitForTimeout(200);
const sentMatch = await page.getByText('Automated E2E Verification Complete').count();
console.log('Sent message found in Sent folder:', sentMatch);
if (sentMatch < 1) throw new Error('Sent message not found in Sent folder!');

// 6. Test Dark Mode & Split Reading Pane
await page.getByRole('button', { name: /^Inbox/i }).click();
await page.waitForTimeout(150);
await page.getByLabel('Settings').click();
await page.waitForTimeout(150);
await page.getByRole('button', { name: /^Dark$/i }).click();
await page.getByRole('button', { name: /Right of inbox/i }).click();
await page.getByLabel('Close quick settings').click();
await page.getByText('Series C Board Deck').first().click();
await page.waitForTimeout(250);
await page.screenshot({ path: path.join(outDir, '06-dark-split-pane.png') });

// Switch back to Light Mode & No Split for clean mobile check
await page.getByLabel('Switch to light theme').click();
await page.getByLabel('Toggle split pane mode').click();
await page.getByRole('button', { name: /No split/i }).click();
await page.waitForTimeout(150);

// 7. Mobile Viewport Check
await page.setViewportSize({ width: 390, height: 844 });
await page.waitForTimeout(200);
await page.screenshot({ path: path.join(outDir, '07-mobile-inbox.png') });
await page.getByLabel('Main menu').click();
await page.waitForTimeout(200);
await page.screenshot({ path: path.join(outDir, '08-mobile-drawer.png') });

await browser.close();

if (errors.length > 0) {
  console.error('Console/Page errors:', errors);
  process.exit(1);
}
console.log('ALL E2E CHECKS PASSED WITH 0 ERRORS!');

